ALTER TABLE public.bookings ADD COLUMN request_expires_at timestamptz, ADD COLUMN service_title_snapshot text, ADD COLUMN duration_minutes_snapshot integer, ADD COLUMN policy_acknowledged_at timestamptz;
CREATE FUNCTION public.aviv_create_guest_request(_service_slug text,_name text,_email text,_phone text,_requested timestamptz,_alternative timestamptz,_token_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.services%ROWTYPE; b public.bookings%ROWTYPE; BEGIN SELECT * INTO s FROM public.services WHERE slug=_service_slug AND active AND published FOR SHARE; IF NOT FOUND OR s.price_minor<=0 THEN RAISE EXCEPTION 'Service unavailable'; END IF; IF length(trim(_name)) NOT BETWEEN 2 AND 100 OR length(_email)>254 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(coalesce(_phone,''))>30 OR _token_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid booking details'; END IF; IF _requested<=now() OR _requested>now()+interval '180 days' OR (_alternative IS NOT NULL AND (_alternative<=now() OR _alternative>now()+interval '180 days' OR _alternative=_requested)) THEN RAISE EXCEPTION 'Invalid requested time'; END IF; INSERT INTO public.bookings(public_reference,client_name,client_email,client_phone,service_id,price_minor,currency,requested_start,alternative_start,time_zone,request_expires_at,service_title_snapshot,duration_minutes_snapshot,policy_acknowledged_at) VALUES('AVIV-'||encode(gen_random_bytes(12),'hex'),trim(_name),lower(trim(_email)),nullif(trim(_phone),''),s.id,s.price_minor,s.currency,_requested,_alternative,'Africa/Lagos',now()+interval '30 minutes',s.title,s.duration_minutes,now()) RETURNING * INTO b; INSERT INTO public.booking_access_tokens(booking_id,token_hash,purpose,expires_at) VALUES(b.id,_token_hash,'manage',now()+interval '30 days'); RETURN jsonb_build_object('id',b.id,'reference',b.public_reference,'price_minor',b.price_minor,'currency',b.currency,'expires_at',b.request_expires_at); END $$;
REVOKE ALL ON FUNCTION public.aviv_create_guest_request(text,text,text,text,timestamptz,timestamptz,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.aviv_create_guest_request(text,text,text,text,timestamptz,timestamptz,text) TO service_role;
CREATE FUNCTION public.aviv_read_guest_booking(_hash text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('reference',b.public_reference,'service',coalesce(b.service_title_snapshot,s.title),'price_minor',b.price_minor,'currency',b.currency,'requested_start',b.requested_start,'alternative_start',b.alternative_start,'confirmed_start',b.confirmed_start,'confirmed_end',b.confirmed_end,'payment_status',b.payment_status,'booking_status',b.booking_status,'request_expired',b.request_expires_at IS NOT NULL AND b.request_expires_at<=now(),'time_zone',b.time_zone) FROM public.booking_access_tokens t JOIN public.bookings b ON b.id=t.booking_id JOIN public.services s ON s.id=b.service_id WHERE t.token_hash=_hash AND t.purpose='manage' AND t.revoked_at IS NULL AND t.expires_at>now() LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.aviv_read_guest_booking(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.aviv_read_guest_booking(text) TO service_role;